USE CATALOG campign;

CREATE SCHEMA IF NOT EXISTS silver;

CREATE TABLE IF NOT EXISTS silver.client (
    client_ref string NOT NULL PRIMARY KEY COMMENT '[DCP] Reference pseudonymisee du client',
    annee_naissance int COMMENT '[DCP] Annee de naissance (la date complete n est pas gardee)',
    pays_residence string COMMENT '[DCP] Pays de residence'
) COMMENT 'Client pseudonymise. Grain : un client';

CREATE TABLE IF NOT EXISTS silver.canal (
    canal_code string NOT NULL PRIMARY KEY COMMENT 'DIRECT, BOOKING, CAMPINGS...',
    libelle string COMMENT 'Libelle du canal',
    est_ota boolean COMMENT 'Vrai si le canal est une agence en ligne (OTA)'
) COMMENT 'Canaux de vente. Grain : un canal';

CREATE TABLE IF NOT EXISTS silver.camping (
    camping_nom string NOT NULL PRIMARY KEY COMMENT 'Nom du camping, identifiant (ex. Les Dunes)',
    commune string COMMENT 'Commune a qui la taxe de sejour est reversee',
    classement_etoiles int COMMENT 'Classement en etoiles (3 ou 4)',
    tarif_taxe_adulte_nuit decimal(5, 2) COMMENT 'Tarif de la taxe par adulte et par nuit, en euros (0,60 pour l exercice)'
) COMMENT 'Les 4 campings du groupe. Grain : un camping';

CREATE TABLE IF NOT EXISTS silver.categorie (
    categorie_code string NOT NULL PRIMARY KEY COMMENT 'NU nu, MH mobil-home, PR premium',
    libelle string COMMENT 'Libelle de la categorie'
) COMMENT 'Referentiel des categories. Grain : une categorie';

CREATE TABLE IF NOT EXISTS silver.emplacement (
    emplacement_id string NOT NULL PRIMARY KEY COMMENT 'Identifiant de l emplacement (ex. E05)',
    camping_nom string NOT NULL COMMENT 'Camping de l emplacement',
    categorie_code string NOT NULL COMMENT 'Categorie de l emplacement'
) COMMENT 'Emplacements loues. Grain : un emplacement';

CREATE TABLE IF NOT EXISTS silver.sejour (
    sejour_id string NOT NULL PRIMARY KEY COMMENT 'Identifiant du sejour dans le PMS (ex. S005)',
    client_ref string COMMENT 'Client pseudonymise',
    emplacement_id string NOT NULL COMMENT 'Emplacement reserve',
    canal_code string NOT NULL COMMENT 'Canal de vente',
    date_arrivee date NOT NULL COMMENT 'Date d arrivee (premiere nuit)',
    date_depart date NOT NULL COMMENT 'Date de depart (nuit non comptee)',
    nb_adultes int COMMENT 'Nombre d adultes, soumis a la taxe de sejour',
    nb_mineurs int COMMENT 'Nombre de mineurs, exoneres',
    montant_ttc decimal(10, 2) COMMENT 'Montant total du sejour en euros TTC'
) COMMENT 'Sejours valides ; la regle depart apres arrivee refuse les autres. Grain : un sejour';

CREATE TABLE IF NOT EXISTS silver.reservation_ota (
    ota_ref string NOT NULL PRIMARY KEY COMMENT 'Identifiant chez l OTA (different de sejour_id)',
    canal_code string NOT NULL,
    emplacement_id string,
    date_arrivee date,
    date_depart date,
    montant_ttc decimal(10, 2),
    sejour_id string COMMENT 'Sejour PMS rapproche (doublon), vide sinon',
    statut_rapprochement string COMMENT 'Resultat du rapprochement avec le PMS (doublon, sans equivalent)'
) COMMENT 'Reservations OTA, rapprochees du sejour PMS quand il existe. Grain : une reservation OTA';

CREATE TABLE IF NOT EXISTS silver.releve_compteur (
    emplacement_id string NOT NULL,
    horodatage timestamp NOT NULL COMMENT 'Date et heure du releve (toutes les 15 minutes)',
    kwh_cumul double COMMENT 'Index electrique cumule en kWh',
    litres_cumul double COMMENT 'Index d eau cumule en litres',
    CONSTRAINT pk_releve_compteur PRIMARY KEY (emplacement_id, horodatage)
) COMMENT 'Releves des compteurs, types. Grain : un emplacement x un quart d heure';

CREATE TABLE IF NOT EXISTS silver.nuitee (
    sejour_id string NOT NULL COMMENT 'Sejour dont vient la nuit',
    date_nuit date NOT NULL COMMENT 'Soir passe sur place ; de date_arrivee incluse a date_depart exclue',
    emplacement_id string NOT NULL COMMENT 'Emplacement occupe cette nuit',
    camping_nom string NOT NULL COMMENT 'Camping de l emplacement, recopie pour agreger vite',
    categorie_code string NOT NULL COMMENT 'Categorie de l emplacement valable cette nuit-la',
    canal_code string NOT NULL COMMENT 'Canal de vente du sejour',
    nb_adultes int COMMENT 'Adultes presents ; base de la taxe de sejour',
    nb_mineurs int COMMENT 'Mineurs presents ; exoneres',
    montant_nuit decimal(10, 2) COMMENT 'montant_ttc du sejour / nombre de nuits, euros TTC',
    mois_nuit string COMMENT 'Mois de la nuit AAAA-MM (une nuit du 31/08 compte en aout)',
    CONSTRAINT pk_nuitee PRIMARY KEY (sejour_id, date_nuit)
) COMMENT 'Table centrale. Une ligne = un sejour x une nuit ; la nuit du depart n est pas comptee';

CREATE TABLE IF NOT EXISTS silver.client_identite (
    client_ref string NOT NULL PRIMARY KEY COMMENT '[DCP] Reference du client, lien avec silver.client',
    nom string COMMENT '[DCP] Nom',
    prenom string COMMENT '[DCP] Prenom',
    email string COMMENT '[DCP] E-mail, masque sauf pour le service client',
    telephone string COMMENT '[DCP] Telephone, masque sauf pour le service client',
    adresse string COMMENT '[DCP] Adresse postale (facturation)',
    code_postal string COMMENT '[DCP] Code postal',
    ville string COMMENT '[DCP] Ville',
    date_creation date COMMENT '[DCP] Date de creation de la fiche',
    date_derniere_activite date COMMENT '[DCP] Dernier sejour ou contact ; point de depart de la conservation de 36 mois'
) COMMENT 'Identite du client, a part et protegee ; effacee 36 mois apres la derniere activite. Grain : un client';

CREATE TABLE IF NOT EXISTS silver.finalite_traitement (
    finalite_code string NOT NULL PRIMARY KEY COMMENT 'CONTRAT, COMPTA, POLICE, STATS, MARKETING',
    libelle string COMMENT 'Pour quoi faire',
    base_legale string COMMENT 'Base legale RGPD article 6 (a verifier, S4.4)',
    duree_conservation_mois int COMMENT 'Duree de conservation en mois',
    point_de_depart string COMMENT 'Evenement qui declenche la duree',
    donnees_et_source string COMMENT 'Donnees concernees et leur source'
) COMMENT 'Referentiel des finalites, base legale et duree de conservation. Grain : une finalite';

CREATE TABLE IF NOT EXISTS silver.consentement (
    client_ref string NOT NULL COMMENT '[DCP] Client qui a fait le choix',
    finalite_code string NOT NULL COMMENT 'Finalite concernee (STATS ou MARKETING)',
    horodatage timestamp NOT NULL COMMENT 'Date et heure du choix ; preuve. Un choix sans date est rejete',
    statut string NOT NULL COMMENT 'ACCORDE, REFUSE ou RETIRE ; le dernier choix compte',
    canal string COMMENT 'WEB ou ACCUEIL',
    version_texte string COMMENT 'Version du texte d information montre au client ; preuve',
    CONSTRAINT pk_consentement PRIMARY KEY (client_ref, finalite_code, horodatage)
) COMMENT 'Journal des consentements, un evenement par ligne. Grain : un choix d un client pour une finalite a un instant';

USE silver;

ALTER TABLE campign.silver.emplacement
ADD CONSTRAINT categorie_connue CHECK (categorie_code IN ('NU', 'MH', 'PR'));

ALTER TABLE campign.silver.sejour
ADD CONSTRAINT dates_coherentes CHECK (date_depart > date_arrivee);

ALTER TABLE campign.silver.sejour
ADD CONSTRAINT personnes_valides CHECK (
        nb_adultes >= 1
        AND nb_mineurs >= 0
    );

ALTER TABLE campign.silver.sejour
ADD CONSTRAINT montant_positif CHECK (montant_ttc >= 0);

ALTER TABLE campign.silver.reservation_ota
ADD CONSTRAINT dates_coherentes_ota CHECK (date_depart > date_arrivee);

ALTER TABLE campign.silver.releve_compteur
ADD CONSTRAINT index_positifs CHECK (
        kwh_cumul >= 0
        AND litres_cumul >= 0
    );

ALTER TABLE campign.silver.nuitee
ADD CONSTRAINT montant_nuit_positif CHECK (montant_nuit >= 0);

ALTER TABLE campign.silver.finalite_traitement
ADD CONSTRAINT duree_positive CHECK (duree_conservation_mois > 0);

ALTER TABLE campign.silver.consentement
ADD CONSTRAINT statut_valide CHECK (statut IN ('ACCORDE', 'REFUSE', 'RETIRE'));

ALTER TABLE silver.emplacement
ADD CONSTRAINT fk_emplacement_camping FOREIGN KEY (camping_nom) REFERENCES silver.camping(camping_nom);

ALTER TABLE silver.emplacement
ADD CONSTRAINT fk_emplacement_categorie FOREIGN KEY (categorie_code) REFERENCES silver.categorie(categorie_code);

ALTER TABLE silver.sejour
ADD CONSTRAINT fk_sejour_client FOREIGN KEY (client_ref) REFERENCES silver.client(client_ref);

ALTER TABLE silver.sejour
ADD CONSTRAINT fk_sejour_emplacement FOREIGN KEY (emplacement_id) REFERENCES silver.emplacement(emplacement_id);

ALTER TABLE silver.sejour
ADD CONSTRAINT fk_sejour_canal FOREIGN KEY (canal_code) REFERENCES silver.canal(canal_code);

ALTER TABLE silver.reservation_ota
ADD CONSTRAINT fk_ota_canal FOREIGN KEY (canal_code) REFERENCES silver.canal(canal_code);

ALTER TABLE silver.reservation_ota
ADD CONSTRAINT fk_ota_emplacement FOREIGN KEY (emplacement_id) REFERENCES silver.emplacement(emplacement_id);

ALTER TABLE silver.reservation_ota
ADD CONSTRAINT fk_ota_sejour FOREIGN KEY (sejour_id) REFERENCES silver.sejour(sejour_id);

ALTER TABLE silver.releve_compteur
ADD CONSTRAINT fk_releve_emplacement FOREIGN KEY (emplacement_id) REFERENCES silver.emplacement(emplacement_id);

ALTER TABLE silver.nuitee
ADD CONSTRAINT fk_nuitee_sejour FOREIGN KEY (sejour_id) REFERENCES silver.sejour(sejour_id);

ALTER TABLE silver.nuitee
ADD CONSTRAINT fk_nuitee_emplacement FOREIGN KEY (emplacement_id) REFERENCES silver.emplacement(emplacement_id);

ALTER TABLE silver.nuitee
ADD CONSTRAINT fk_nuitee_camping FOREIGN KEY (camping_nom) REFERENCES silver.camping(camping_nom);

ALTER TABLE silver.nuitee
ADD CONSTRAINT fk_nuitee_categorie FOREIGN KEY (categorie_code) REFERENCES silver.categorie(categorie_code);

ALTER TABLE silver.nuitee
ADD CONSTRAINT fk_nuitee_canal FOREIGN KEY (canal_code) REFERENCES silver.canal(canal_code);

ALTER TABLE silver.client_identite
ADD CONSTRAINT fk_identite_client FOREIGN KEY (client_ref) REFERENCES silver.client(client_ref);

ALTER TABLE silver.consentement
