USE CATALOG campign;

CREATE SCHEMA IF NOT EXISTS gold;

CREATE TABLE IF NOT EXISTS gold.dp_occupation_yield (
    date_nuit date NOT NULL COMMENT 'Nuit concernee',
    camping_nom string NOT NULL COMMENT 'Camping',
    categorie_code string NOT NULL COMMENT 'NU nu, MH mobil-home, PR premium',
    nb_emplacements_disponibles int COMMENT 'Emplacements de la categorie ouverts a la vente cette nuit',
    nb_emplacements_occupes int COMMENT 'Emplacements ayant une nuitee cette nuit',
    taux_occupation decimal(5, 4) COMMENT 'occupes / disponibles, entre 0 et 1. Sur plusieurs categories : somme des occupes / somme des disponibles, jamais la moyenne des taux',
    chiffre_affaires decimal(12, 2) COMMENT 'Somme des montant_nuit, euros TTC',
    prix_moyen_nuit decimal(10, 2) COMMENT 'chiffre_affaires / occupes',
    revpar decimal(10, 2) COMMENT 'chiffre_affaires / disponibles',
    nb_nuitees_direct int COMMENT 'Nuitees vendues en direct (canal.est_ota = faux)',
    nb_nuitees_ota int COMMENT 'Nuitees vendues par une OTA (canal.est_ota = vrai)',
    part_direct decimal(5, 4) COMMENT 'nb_nuitees_direct / occupes, entre 0 et 1',
    taux_occupation_n1 decimal(5, 4) COMMENT 'Taux de la meme date l annee precedente ; vide si inconnu',
    CONSTRAINT pk_dp_occupation_yield PRIMARY KEY (date_nuit, camping_nom, categorie_code)
) COMMENT 'Data product de la direction commerciale. Grain : une nuit x un camping x une categorie. Mis a jour chaque nuit, pret a 6 h. Aucune donnee personnelle';

USE gold;

ALTER TABLE campign.gold.dp_occupation_yield
ADD CONSTRAINT taux_valide CHECK (
        taux_occupation BETWEEN 0 AND 1
    );

ALTER TABLE campign.gold.dp_occupation_yield
ADD CONSTRAINT occupes_le_disponibles CHECK (
        nb_emplacements_occupes <= nb_emplacements_disponibles
    );

ALTER TABLE campign.gold.dp_occupation_yield
ADD CONSTRAINT part_direct_valide CHECK (
        part_direct BETWEEN 0 AND 1
    );

ALTER TABLE gold.dp_occupation_yield
ADD CONSTRAINT fk_dp_occ_camping FOREIGN KEY (camping_nom) REFERENCES silver.camping(camping_nom);

ALTER TABLE gold.dp_occupation_yield
ADD CONSTRAINT fk_dp_occ_categorie FOREIGN KEY (categorie_code) REFERENCES silver.categorie(categorie_code);

